<?php use VazinCMS\Security;require __DIR__.'/partials/head.php';?><section class="page-head"><h1>ماژول‌های سایت</h1><p>سایت خام است؛ فقط ماژول‌هایی را فعال کنید که همین دامنه نیاز دارد.</p></section><section class="grid two"><?php foreach($modules as $module):?><article class="card"><h2><?=Security::e($module['name'])?></h2><p><?=Security::e($module['description'])?></p><p>نسخه <?=Security::e($module['version']?:'—')?> — <?=$module['is_enabled']?'فعال':'غیرفعال'?></p><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="module_key" value="<?=Security::e($module['module_key'])?>"><button><?=$module['is_enabled']?'غیرفعال‌سازی':'فعال‌سازی'?></button></form></article><?php endforeach;?></section><?php require __DIR__.'/partials/foot.php';?>
